"""Turn the effective configuration + theme into concrete config files.

Two kinds of output:

* Generated files in ~/.local/state/surfd/generated/ (Sway, Waybar,
  session environment, greeter style). Always overwritten.
* Managed files in the standard places apps look for them (GTK, foot,
  fuzzel, mako, swaylock, qt6ct). They start with a "Managed by surfctl"
  marker. Delete the marker line and surfctl leaves that file alone —
  that is how you take over one app's config by hand.
"""

from __future__ import annotations

import json
import os
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from . import color, config, keys, paths, themes
from .themes import Palette, Theme

MARKER = "Managed by surfctl"
LIBEXEC = Path(os.environ.get("SURFD_LIBEXEC", "/usr/libexec/surfd"))


def _header(comment: str, what: str) -> str:
    return (f"{comment} {MARKER} from ~/.config/surfd/surfd.toml — {what}.\n"
            f"{comment} Change settings with `surfctl` or Surf Settings. Delete this line to\n"
            f"{comment} take this file over by hand; surfctl will then leave it alone.\n")


@dataclass
class Context:
    cfg: dict[str, Any]
    theme: Theme
    pal: Palette
    gen: Path

    def c(self, dotted: str) -> Any:
        return config.get(self.cfg, dotted)

    @property
    def wallpaper(self) -> Path | None:
        custom = self.c("wallpaper.path") or ""
        if custom:
            p = Path(os.path.expanduser(custom))
            if p.is_file():
                return p
        return self.theme.wallpaper(self.pal.variant)

    @property
    def floating_mode(self) -> bool:
        return self.c("layout.mode") == "floating"


def build_context(cfg: dict[str, Any] | None = None) -> Context:
    cfg = cfg if cfg is not None else config.load()
    theme, pal = themes.resolve(cfg)
    return Context(cfg=cfg, theme=theme, pal=pal, gen=paths.generated_dir())


# ===================================================================== sway ==

def sway(ctx: Context) -> str:
    p, c = ctx.pal, ctx.c
    border = int(c("layout.border_width"))
    titlebars = ctx.floating_mode or bool(c("layout.titlebars"))
    out: list[str] = [
        "# Generated by surfctl from ~/.config/surfd/surfd.toml — do not edit.",
        "# Raw Sway additions: put *.conf files in ~/.config/surfd/sway.d/",
        "",
        f"set $mod {keys.MODIFIERS[c('keys.modifier').lower()]}",
        f"font pango:{c('fonts.ui')} {max(int(c('fonts.size')) - 1, 6)}",
        "xwayland enable",
        f"focus_follows_mouse {'yes' if c('layout.focus_follows_mouse') else 'no'}",
        "mouse_warping output",
        "floating_modifier $mod normal",
        "tiling_drag enable",
        f"default_border {'normal' if titlebars else 'pixel'} {border}",
        f"default_floating_border normal {border}",
        "titlebar_padding 10 5",
        f"gaps inner {int(c('layout.gaps_inner'))}",
        f"gaps outer {int(c('layout.gaps_outer'))}",
        "",
        "# colours: border background text indicator child_border",
        f"client.focused          {p.accent} {p.accent} {p.accent_text} {p.accent} {p.accent}",
        f"client.focused_inactive {p.surface_alt} {p.surface_alt} {p.text} {p.border} {p.border}",
        f"client.unfocused        {p.surface} {p.surface} {p.text_muted} {p.border} {p.border}",
        f"client.urgent           {p.urgent} {p.urgent} {color.readable_on(p.urgent)} {p.urgent} {p.urgent}",
        f"client.placeholder      {p.background} {p.background} {p.text} {p.background} {p.background}",
        f"client.background       {p.background}",
        "",
    ]

    wp = ctx.wallpaper
    if wp is not None:
        out.append(f'output * bg "{wp}" {c("wallpaper.mode")} {p.background}')
    else:
        out.append(f"output * bg {p.background} solid_color")
    scale = float(c("display.scale"))
    if scale > 0:
        out.append(f"output * scale {scale:g}")
    out.append(f"seat seat0 xcursor_theme {ctx.theme.cursor_theme} {ctx.theme.cursor_size}")

    accel = float(c("input.pointer_accel"))
    kb = [f'    xkb_layout "{c("input.keyboard_layout")}"']
    if c("input.keyboard_variant"):
        kb.append(f'    xkb_variant "{c("input.keyboard_variant")}"')
    if c("input.keyboard_options"):
        kb.append(f'    xkb_options "{c("input.keyboard_options")}"')
    out += [
        "",
        "input type:keyboard {",
        *kb,
        "    repeat_delay 300",
        "    repeat_rate 40",
        "}",
        "input type:touchpad {",
        f"    tap {'enabled' if c('input.touchpad_tap') else 'disabled'}",
        f"    natural_scroll {'enabled' if c('input.natural_scroll') else 'disabled'}",
        "    dwt enabled",
        "    middle_emulation enabled",
        f"    pointer_accel {accel:g}",
        "}",
        "input type:pointer {",
        "    accel_profile adaptive",
        f"    pointer_accel {accel:g}",
        "}",
        "",
        "# dialogs, utilities and pop-ups float",
        'for_window [window_role="pop-up"] floating enable',
        'for_window [window_role="dialog"] floating enable',
        'for_window [window_type="dialog"] floating enable',
        'for_window [app_id="^(org.pulseaudio.pavucontrol|pavucontrol|blueman-manager|nm-connection-editor)$"] '
        "floating enable, resize set 760 520",
        'for_window [app_id="^org.surfd.(Settings|Welcome)$"] floating enable',
        'for_window [title="^Picture-in-Picture$"] floating enable, sticky enable',
        "for_window [all] inhibit_idle fullscreen",
    ]
    if ctx.floating_mode:
        out += [
            "",
            "# mouse-friendly mode: every window floats with a title bar",
            "for_window [all] floating enable",
        ]

    out += ["", "# key bindings (from [keys.bindings])"]
    for b in keys.compile_bindings(ctx.cfg):
        flags = "--to-code" + (" --locked" if b.locked else "")
        out.append(f"bindsym {flags} {b.sway_combo} {b.command}")

    out += [
        "",
        'mode "resize" {',
        "    bindsym Left resize shrink width 20px",
        "    bindsym Right resize grow width 20px",
        "    bindsym Up resize shrink height 20px",
        "    bindsym Down resize grow height 20px",
        "    bindsym h resize shrink width 20px",
        "    bindsym l resize grow width 20px",
        "    bindsym k resize shrink height 20px",
        "    bindsym j resize grow height 20px",
        '    bindsym Return mode "default"',
        '    bindsym Escape mode "default"',
        "}",
    ]

    if c("input.gestures"):
        out += [
            "",
            "# touchpad gestures",
            "bindgesture swipe:3:left workspace next_on_output",
            "bindgesture swipe:3:right workspace prev_on_output",
            f"bindgesture swipe:3:up exec {c('apps.launcher')}",
            "bindgesture swipe:4:up fullscreen toggle",
        ]

    lock = int(c("idle.lock_after"))
    off = int(c("idle.screen_off_after"))
    susp = int(c("idle.suspend_after"))
    waybar_cfg = ctx.gen / "waybar" / "config.jsonc"
    waybar_css = ctx.gen / "waybar" / "style.css"
    out += [
        "",
        "# session",
        "exec systemctl --user import-environment DISPLAY WAYLAND_DISPLAY SWAYSOCK "
        "XDG_CURRENT_DESKTOP XDG_SESSION_TYPE",
        "exec dbus-update-activation-environment --systemd DISPLAY WAYLAND_DISPLAY SWAYSOCK "
        "XDG_CURRENT_DESKTOP XDG_SESSION_TYPE",
        "exec systemctl --user start surfd-session.target",
        "exec lxpolkit",
        "exec mako",
        "exec_always makoctl reload",
        f'exec_always {LIBEXEC}/surfd-bar "{waybar_cfg}" "{waybar_css}"',
        f"exec_always {LIBEXEC}/surfd-idle {lock} {off} {susp}",
        "exec surfctl apply --desktop-settings",
        "exec surfctl doctor --notify --quiet",
        "exec surfctl first-run",
    ]
    for cmd in c("autostart.commands"):
        if any(ch in cmd for ch in ";,\n"):
            continue  # validated elsewhere; never emit something Sway would split
        out.append(f"exec {cmd}")
    out += [
        "",
        "# system-wide and personal additions (last, so they can override)",
        "include /etc/surfd/sway.d/*.conf",
        f"include {paths.user_config_dir()}/sway.d/*.conf",
        "",
    ]
    return "\n".join(out)


# =================================================================== waybar ==

WAYBAR_MODULE_NAMES = {
    "workspaces": "sway/workspaces",
    "mode": "sway/mode",
    "window": "sway/window",
    "taskbar": "wlr/taskbar",
    "clock": "clock",
    "tray": "tray",
    "network": "network",
    "audio": "pulseaudio",
    "battery": "battery",
    "backlight": "backlight",
    "bluetooth": "bluetooth",
    "cpu": "cpu",
    "memory": "memory",
    "temperature": "temperature",
    "keyboard": "sway/language",
    "media": "mpris",
    "idle": "idle_inhibitor",
    "power": "custom/power",
}


def _lbl(label: str, value: str) -> str:
    """Muted small label + value, e.g. 'vol 40%'. Pango markup."""
    return f"<span alpha='55%' size='small'>{label}</span> {value}"


def waybar_config(ctx: Context) -> str:
    c = ctx.c
    floating = c("bar.style") == "floating"
    gap = max(int(c("layout.gaps_outer")) + int(c("layout.gaps_inner")), 6) if floating else 0
    pos = c("bar.position")
    conf: dict[str, Any] = {
        "layer": "top",
        "position": pos,
        "height": int(c("bar.height")),
        "spacing": 6,
        "modules-left": [WAYBAR_MODULE_NAMES[m] for m in c("bar.left")],
        "modules-center": [WAYBAR_MODULE_NAMES[m] for m in c("bar.center")],
        "modules-right": [WAYBAR_MODULE_NAMES[m] for m in c("bar.right")],
        "sway/workspaces": {"disable-scroll": False, "all-outputs": False, "format": "{name}"},
        "sway/mode": {"format": "{}"},
        "sway/window": {"max-length": 60, "tooltip": False},
        "wlr/taskbar": {"format": "{icon} {title:.24}", "icon-size": 16, "on-click": "activate",
                        "on-click-middle": "close", "tooltip-format": "{title}"},
        "clock": {"format": "{:%a %d %b  %H:%M}", "tooltip-format": "<tt>{calendar}</tt>",
                  "calendar": {"mode": "month", "format": {"today": "<b><u>{}</u></b>"}}},
        "tray": {"icon-size": 16, "spacing": 8},
        "network": {"format-wifi": _lbl("wifi", "{essid}"), "format-ethernet": _lbl("eth", "{ifname}"),
                    "format-disconnected": _lbl("net", "off"), "tooltip-format": "{ipaddr} via {gwaddr}",
                    "on-click": "surfctl network-menu", "on-click-right": "nm-connection-editor"},
        "pulseaudio": {"format": _lbl("vol", "{volume}%"), "format-muted": _lbl("vol", "muted"),
                       "on-click": "pavucontrol", "scroll-step": 5},
        "battery": {"format": _lbl("bat", "{capacity}%"), "format-charging": _lbl("bat", "{capacity}% +"),
                    "states": {"warning": 25, "critical": 10}, "tooltip-format": "{timeTo}"},
        "backlight": {"format": _lbl("lum", "{percent}%")},
        "bluetooth": {"format": _lbl("bt", "{status}"), "format-connected": _lbl("bt", "{device_alias}"),
                      "on-click": "blueman-manager"},
        "cpu": {"format": _lbl("cpu", "{usage}%"), "interval": 5},
        "memory": {"format": _lbl("mem", "{percentage}%"), "interval": 10},
        "temperature": {"format": _lbl("tmp", "{temperatureC}°"), "critical-threshold": 85},
        "sway/language": {"format": _lbl("kbd", "{short}")},
        "mpris": {"format": "{player_icon} {dynamic}", "dynamic-len": 40,
                  "player-icons": {"default": "▸"}, "status-icons": {"paused": "॥"}},
        "idle_inhibitor": {"format": "{icon}", "format-icons": {"activated": _lbl("awake", "on"),
                                                               "deactivated": _lbl("awake", "off")}},
        "custom/power": {"format": "⏻", "tooltip": False, "on-click": "surfctl power-menu"},
    }
    if floating:
        side = "margin-top" if pos == "top" else "margin-bottom"
        conf[side] = gap
        conf["margin-left"] = gap
        conf["margin-right"] = gap
    header = "// Generated by surfctl from ~/.config/surfd/surfd.toml — do not edit.\n"
    return header + json.dumps(conf, indent=2, ensure_ascii=False) + "\n"


def waybar_css(ctx: Context) -> str:
    p, c = ctx.pal, ctx.c
    r = int(c("layout.radius"))
    floating = c("bar.style") == "floating"
    bar_bg = color.rgba(p.surface, 0.92 if floating else 1.0)
    css = f"""/* Generated by surfctl from ~/.config/surfd/surfd.toml — do not edit. */
* {{
  font-family: "{c('fonts.ui')}", sans-serif;
  font-size: {int(c('fonts.size')) + 1}pt;
  min-height: 0;
  border: none;
}}

window#waybar {{
  background: {bar_bg};
  color: {p.text};
  border-radius: {r if floating else 0}px;
  border: {'1px solid ' + color.rgba(p.text, 0.08) if floating else 'none'};
  transition: background-color 200ms ease;
}}

tooltip {{
  background: {p.surface};
  border: 1px solid {p.border};
  border-radius: {max(r - 2, 0)}px;
}}
tooltip label {{ color: {p.text}; }}

#workspaces {{ margin: 0 4px; }}
#workspaces button {{
  padding: 0 9px;
  margin: 4px 2px;
  color: {p.text_muted};
  background: transparent;
  border-radius: {max(r - 4, 0)}px;
  transition: background-color 150ms ease, color 150ms ease, padding 150ms ease;
}}
#workspaces button:hover {{ background: {p.surface_alt}; color: {p.text}; box-shadow: none; }}
#workspaces button.focused {{ background: {p.accent}; color: {p.accent_text}; padding: 0 14px; }}
#workspaces button.urgent {{ background: {p.urgent}; color: {color.readable_on(p.urgent)}; }}

#mode {{
  background: {p.warning};
  color: {color.readable_on(p.warning)};
  border-radius: {max(r - 4, 0)}px;
  padding: 0 10px;
  margin: 4px;
}}

#window, #clock, #tray, #network, #pulseaudio, #battery, #backlight, #bluetooth,
#cpu, #memory, #temperature, #language, #mpris, #idle_inhibitor, #custom-power, #taskbar {{
  padding: 0 10px;
  margin: 4px 0;
  color: {p.text};
  border-radius: {max(r - 4, 0)}px;
  transition: background-color 150ms ease;
}}
#clock {{ font-weight: 600; }}
#window {{ color: {p.text_muted}; }}
#network:hover, #pulseaudio:hover, #bluetooth:hover, #custom-power:hover, #clock:hover {{
  background: {p.surface_alt};
}}
#taskbar button {{ padding: 0 8px; border-radius: {max(r - 4, 0)}px; color: {p.text_muted}; }}
#taskbar button.active {{ background: {p.surface_alt}; color: {p.text}; }}
#battery.warning {{ color: {p.warning}; }}
#battery.critical:not(.charging) {{ color: {p.urgent}; }}
#network.disconnected, #pulseaudio.muted {{ color: {p.text_muted}; }}
#temperature.critical {{ color: {p.urgent}; }}
#idle_inhibitor.activated {{ color: {p.accent}; }}
#custom-power {{ color: {p.accent}; margin-right: 4px; }}
"""
    extra = ctx.theme.extra("waybar.css")
    if extra:
        css += f"\n/* from theme {ctx.theme.name}: waybar.css */\n{extra}"
    return css


# ===================================================== notifications (mako) ==

def mako(ctx: Context) -> str:
    p, c = ctx.pal, ctx.c
    gap = int(c("layout.gaps_outer")) + int(c("layout.gaps_inner")) + 2
    return _header("#", "notifications (mako)") + f"""
font={c('fonts.ui')} {c('fonts.size')}
background-color={p.surface}f2
text-color={p.text}
border-color={p.border}
progress-color=over {p.accent}
border-size=1
border-radius={int(c('layout.radius'))}
padding=14
margin={gap}
width=380
max-visible=4
icons=1
max-icon-size=40
icon-path=/usr/share/icons/{p.icon_theme}
anchor={c('notifications.position')}
default-timeout={int(c('notifications.timeout'))}
layer=overlay

[urgency=low]
text-color={p.text_muted}

[urgency=high]
border-color={p.urgent}
border-size=2
default-timeout=0
"""


# ======================================================= launcher (fuzzel) ==

def fuzzel(ctx: Context) -> str:
    p, c = ctx.pal, ctx.c
    return _header("#", "app launcher (fuzzel)") + f"""
[main]
font={c('fonts.ui')}:size={int(c('fonts.size')) + 2}
terminal={c('apps.terminal')} -e
icon-theme={p.icon_theme}
prompt="> "
width=36
lines=9
horizontal-pad=22
vertical-pad=16
inner-pad=10
line-height={int(c('fonts.size')) + 15}
layer=overlay
exit-on-keyboard-focus-loss=yes

[colors]
background={color.hex_alpha(p.surface, 0.97)}
text={color.hex_alpha(p.text, 1)}
match={color.hex_alpha(p.accent, 1)}
selection={color.hex_alpha(p.surface_alt, 1)}
selection-text={color.hex_alpha(p.text, 1)}
selection-match={color.hex_alpha(p.accent, 1)}
border={color.hex_alpha(p.accent, 0.85)}

[border]
width=2
radius={int(c('layout.radius'))}
"""


# ================================================================ terminal ==

def foot(ctx: Context) -> str:
    p, c = ctx.pal, ctx.c
    t = [color.hex_no_hash(x) for x in p.terminal]
    lines = [_header("#", "terminal (foot)"), "[main]",
             f"font={c('fonts.mono')}:size={c('fonts.mono_size')}",
             "pad=14x12 center", "", "[cursor]", "style=beam", "blink=yes", "",
             "[mouse]", "hide-when-typing=yes", "", "[colors]",
             "alpha=0.97",
             f"foreground={color.hex_no_hash(p.text)}",
             f"background={color.hex_no_hash(p.background)}",
             f"selection-foreground={color.hex_no_hash(p.accent_text)}",
             f"selection-background={color.hex_no_hash(p.accent)}",
             f"urls={color.hex_no_hash(p.accent)}"]
    lines += [f"regular{i}={t[i]}" for i in range(8)]
    lines += [f"bright{i}={t[i + 8]}" for i in range(8)]
    return "\n".join(lines) + "\n"


# ============================================================= lock screen ==

def swaylock(ctx: Context) -> str:
    p, c = ctx.pal, ctx.c
    h = color.hex_alpha
    lines = [_header("#", "lock screen (swaylock)"),
             f"font={c('fonts.ui')}",
             "indicator-radius=90",
             "indicator-thickness=7",
             "show-failed-attempts",
             "ignore-empty-password",
             f"color={color.hex_no_hash(p.background)}",
             f"inside-color={h(p.surface, 0.85)}",
             f"inside-clear-color={h(p.surface, 0.85)}",
             f"inside-ver-color={h(p.surface, 0.85)}",
             f"inside-wrong-color={h(p.surface, 0.85)}",
             f"ring-color={h(p.surface_alt, 1)}",
             f"ring-ver-color={h(p.accent, 1)}",
             f"ring-clear-color={h(p.warning, 1)}",
             f"ring-wrong-color={h(p.urgent, 1)}",
             f"key-hl-color={h(p.accent, 1)}",
             f"bs-hl-color={h(p.warning, 1)}",
             f"text-color={h(p.text, 1)}",
             f"text-ver-color={h(p.text, 1)}",
             f"text-wrong-color={h(p.urgent, 1)}",
             f"text-clear-color={h(p.text, 1)}",
             "line-color=00000000", "line-ver-color=00000000",
             "line-wrong-color=00000000", "line-clear-color=00000000",
             "separator-color=00000000"]
    wp = ctx.wallpaper
    if wp is not None and wp.suffix.lower() != ".svg":
        lines += [f"image={wp}", "scaling=fill"]
    return "\n".join(lines) + "\n"


# ===================================================================== GTK ==

def _gtk_named_colors(p: Palette) -> str:
    view_bg = color.mix(p.background, p.surface, 0.5)
    pairs = {
        "accent_color": p.accent if p.is_dark else color.mix(p.accent, "#000000", 0.15),
        "accent_bg_color": p.accent,
        "accent_fg_color": p.accent_text,
        "destructive_color": p.urgent,
        "destructive_bg_color": p.urgent,
        "destructive_fg_color": color.readable_on(p.urgent),
        "success_color": p.success,
        "warning_color": p.warning,
        "error_color": p.urgent,
        "window_bg_color": p.background,
        "window_fg_color": p.text,
        "view_bg_color": view_bg,
        "view_fg_color": p.text,
        "headerbar_bg_color": p.surface,
        "headerbar_fg_color": p.text,
        "headerbar_backdrop_color": p.background,
        "sidebar_bg_color": p.surface,
        "sidebar_fg_color": p.text,
        "card_bg_color": p.surface,
        "card_fg_color": p.text,
        "popover_bg_color": p.surface,
        "popover_fg_color": p.text,
        "dialog_bg_color": p.surface,
        "dialog_fg_color": p.text,
    }
    return "\n".join(f"@define-color {k} {v};" for k, v in pairs.items())


def gtk3_css(ctx: Context) -> str:
    extra = ctx.theme.extra("gtk.css")
    return (_header("/*", "GTK 3 colours").replace("\n/*", "\n *").rstrip("\n") + " */\n\n"
            + _gtk_named_colors(ctx.pal) + "\n" + (f"\n/* theme extras */\n{extra}" if extra else ""))


def gtk4_css(ctx: Context) -> str:
    p = ctx.pal
    variables = {
        "accent-color": p.accent if p.is_dark else color.mix(p.accent, "#000000", 0.15),
        "accent-bg-color": p.accent,
        "accent-fg-color": p.accent_text,
        "window-bg-color": p.background,
        "window-fg-color": p.text,
        "view-bg-color": color.mix(p.background, p.surface, 0.5),
        "view-fg-color": p.text,
        "headerbar-bg-color": p.surface,
        "headerbar-fg-color": p.text,
        "sidebar-bg-color": p.surface,
        "card-bg-color": p.surface,
        "popover-bg-color": p.surface,
        "dialog-bg-color": p.surface,
        "destructive-bg-color": p.urgent,
        "success-color": p.success,
        "warning-color": p.warning,
        "error-color": p.urgent,
    }
    root = ":root {\n" + "\n".join(f"  --{k}: {v};" for k, v in variables.items()) + "\n}\n"
    extra = ctx.theme.extra("gtk.css")
    # Named colours for libadwaita < 1.6, CSS variables for 1.6 and later.
    return (_header("/*", "GTK 4 / libadwaita colours").replace("\n/*", "\n *").rstrip("\n") + " */\n\n"
            + _gtk_named_colors(p) + "\n\n" + root + (f"\n/* theme extras */\n{extra}" if extra else ""))


def gtk_settings(ctx: Context, version: int) -> str:
    p, c = ctx.pal, ctx.c
    lines = [_header("#", f"GTK {version} settings"), "[Settings]"]
    if version == 3:
        lines.append(f"gtk-theme-name={'adw-gtk3-dark' if p.is_dark else 'adw-gtk3'}")
        lines.append(f"gtk-application-prefer-dark-theme={1 if p.is_dark else 0}")
    lines += [
        f"gtk-icon-theme-name={p.icon_theme}",
        f"gtk-cursor-theme-name={ctx.theme.cursor_theme}",
        f"gtk-cursor-theme-size={ctx.theme.cursor_size}",
        f"gtk-font-name={c('fonts.ui')} {c('fonts.size')}",
        "gtk-enable-animations=1",
        "gtk-decoration-layout=:close",
    ]
    return "\n".join(lines) + "\n"


# ====================================================================== Qt ==

def qt6ct_colors(ctx: Context) -> str:
    p = ctx.pal
    # QPalette roles, in qt6ct order (21 entries).
    def row(fg: str, bg: str, base: str, hl: str, hl_text: str) -> str:
        light = color.mix(bg, "#ffffff", 0.1)
        dark = color.mix(bg, "#000000", 0.3)
        mid = color.mix(bg, "#000000", 0.15)
        vals = [fg, bg, light, color.mix(bg, "#ffffff", 0.05), dark, mid, fg, "#ffffff", fg, base, bg,
                "#000000", hl, hl_text, p.accent, color.mix(p.accent, p.urgent, 0.4),
                color.mix(base, bg, 0.5), "#000000", p.surface, p.text, p.text_muted]
        return ", ".join("#ff" + color.hex_no_hash(v) for v in vals)

    base = color.mix(p.background, p.surface, 0.5)
    disabled_fg = color.mix(p.text, p.background, 0.55)
    return ("[ColorScheme]\n"
            f"active_colors={row(p.text, p.surface, base, p.accent, p.accent_text)}\n"
            f"disabled_colors={row(disabled_fg, p.surface, base, p.surface_alt, disabled_fg)}\n"
            f"inactive_colors={row(p.text, p.surface, base, p.surface_alt, p.text)}\n")


def qt6ct_conf(ctx: Context) -> str:
    p, c = ctx.pal, ctx.c
    scheme = ctx.gen / "qt6ct" / "surfd-colors.conf"
    return (f"; {MARKER} from ~/.config/surfd/surfd.toml. Delete this line to take over.\n"
            "[Appearance]\n"
            f"color_scheme_path={scheme}\n"
            "custom_palette=true\n"
            f"icon_theme={p.icon_theme}\n"
            "standard_dialogs=xdgdesktopportal\n"
            "style=Fusion\n\n"
            "[Fonts]\n"
            f"fixed=\"{c('fonts.mono')},{c('fonts.mono_size')},-1,5,50,0,0,0,0,0\"\n"
            f"general=\"{c('fonts.ui')},{c('fonts.size')},-1,5,50,0,0,0,0,0\"\n")


# ================================================================ session ==

def session_env(ctx: Context) -> str:
    env = {
        "XDG_CURRENT_DESKTOP": "sway",
        "XDG_SESSION_DESKTOP": "sway",
        "XDG_SESSION_TYPE": "wayland",
        "MOZ_ENABLE_WAYLAND": "1",
        "QT_QPA_PLATFORM": "wayland;xcb",
        "QT_QPA_PLATFORMTHEME": "qt6ct",
        "QT_WAYLAND_DISABLE_WINDOWDECORATION": "1",
        "ELECTRON_OZONE_PLATFORM_HINT": "auto",
        "_JAVA_AWT_WM_NONREPARENTING": "1",
        "XCURSOR_THEME": ctx.theme.cursor_theme,
        "XCURSOR_SIZE": str(ctx.theme.cursor_size),
        "GTK_THEME_VARIANT": ctx.pal.variant,
    }
    return "# Generated by surfctl — session environment, sourced by surfd-session\n" + \
        "".join(f"{k}='{v}'\n" for k, v in env.items())


# ================================================================ greeter ==

def greeter_css(ctx: Context, background: str) -> str:
    p, c = ctx.pal, ctx.c
    r = int(c("layout.radius"))
    return f"""/* surfd login screen (gtkgreet). Generated by `surfctl greeter sync`. */
window {{
  background-color: {p.background};
  background-image: url("file://{background}");
  background-size: cover;
  background-position: center;
  font-family: "{c('fonts.ui')}", sans-serif;
}}
box#body {{
  background-color: {color.rgba(p.surface, 0.88)};
  border: 1px solid {color.rgba(p.text, 0.08)};
  border-radius: {r + 6}px;
  padding: 40px 48px;
}}
label {{ color: {p.text}; }}
#clock {{ font-size: 40pt; font-weight: 300; color: {p.text}; }}
entry {{
  background: {p.surface_alt};
  color: {p.text};
  border: 1px solid {p.border};
  border-radius: {max(r - 2, 4)}px;
  padding: 8px 12px;
  min-height: 24px;
}}
entry:focus {{ border-color: {p.accent}; box-shadow: 0 0 0 2px {color.rgba(p.accent, 0.35)}; }}
button {{
  background: {p.accent};
  color: {p.accent_text};
  border: none;
  border-radius: {max(r - 2, 4)}px;
  padding: 8px 18px;
  font-weight: 600;
  transition: background-color 150ms ease;
}}
button:hover {{ background: {color.mix(p.accent, '#ffffff', 0.12)}; }}
combobox button {{ background: {p.surface_alt}; color: {p.text}; }}
"""


# ============================================================ write files ==

@dataclass
class Output:
    path: Path
    content: str
    managed: bool  # lives in an app's own config dir; respects marker takeover


def outputs(ctx: Context) -> list[Output]:
    gen = ctx.gen
    home = paths.config_home()
    return [
        Output(gen / "sway" / "config", sway(ctx), False),
        Output(gen / "waybar" / "config.jsonc", waybar_config(ctx), False),
        Output(gen / "waybar" / "style.css", waybar_css(ctx), False),
        Output(gen / "session.env", session_env(ctx), False),
        Output(gen / "qt6ct" / "surfd-colors.conf", qt6ct_colors(ctx), False),
        Output(home / "mako" / "config", mako(ctx), True),
        Output(home / "fuzzel" / "fuzzel.ini", fuzzel(ctx), True),
        Output(home / "foot" / "foot.ini", foot(ctx), True),
        Output(home / "swaylock" / "config", swaylock(ctx), True),
        Output(home / "gtk-3.0" / "gtk.css", gtk3_css(ctx), True),
        Output(home / "gtk-3.0" / "settings.ini", gtk_settings(ctx, 3), True),
        Output(home / "gtk-4.0" / "gtk.css", gtk4_css(ctx), True),
        Output(home / "gtk-4.0" / "settings.ini", gtk_settings(ctx, 4), True),
        Output(home / "qt6ct" / "qt6ct.conf", qt6ct_conf(ctx), True),
    ]


def _is_ours(path: Path) -> bool:
    try:
        with path.open(encoding="utf-8", errors="replace") as fh:
            head = fh.read(400)
    except OSError:
        return False
    return MARKER in head


@dataclass
class WriteReport:
    written: list[Path]
    unchanged: list[Path]
    skipped: list[Path]  # user took the file over (no marker)


def write_all(ctx: Context, *, dry_run: bool = False) -> WriteReport:
    report = WriteReport([], [], [])
    for out in outputs(ctx):
        if out.managed and out.path.exists() and not _is_ours(out.path):
            report.skipped.append(out.path)
            continue
        if out.path.exists() and out.path.read_text(encoding="utf-8", errors="replace") == out.content:
            report.unchanged.append(out.path)
            continue
        if not dry_run:
            config._atomic_write(out.path, out.content)
        report.written.append(out.path)
    return report
